import heapq


def running_median(stream):
    lower = []  # max-heap of the lower half, values negated
    upper = []  # min-heap of the upper half
    result = []
    for x in stream:
        if lower and x <= -lower[0]:
            heapq.heappush(lower, -x)
        else:
            heapq.heappush(upper, x)
        if len(lower) > len(upper) + 1:
            heapq.heappush(upper, -heapq.heappop(lower))
        elif len(upper) > len(lower) + 1:
            heapq.heappush(lower, -heapq.heappop(upper))
        if len(lower) == len(upper):
            result.append((-lower[0] + upper[0]) / 2)
        elif len(lower) > len(upper):
            result.append(float(-lower[0]))
        else:
            result.append(float(upper[0]))
    return result
